CREATE OR REPLACE FUNCTION public.events_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.allowed_users;
begin
  select * into a from public.allowed_users where id = public.my_allowed_id();
  if not found then raise exception 'session_replaced'; end if;
  new.user_id := a.id;
  new.username := a.username;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.feedback_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.allowed_users;
begin
  select * into a from public.allowed_users where id = public.my_allowed_id();
  if not found then raise exception 'session_replaced'; end if;
  new.user_id := a.id;
  new.username := a.username;
  new.body := btrim(new.body);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.issue_invite(p_username text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';  -- 31 символ
  code  text := '';
  b     int;
  salt  text := encode(gen_random_bytes(16), 'hex');
  uname text := lower(regexp_replace(trim(p_username), '^@', ''));
begin
  if not (session_user in ('postgres', 'supabase_admin') or auth.role() = 'service_role' or public.is_admin_user()) then
    raise exception 'forbidden';
  end if;
  -- рівномірний вибір символа: відкидаємо байти, що дали б зсув (256 = 31*8 + 8)
  while length(code) < 12 loop
    b := get_byte(gen_random_bytes(1), 0);
    if b < 248 then code := code || substr(alphabet, (b % 31) + 1, 1); end if;
  end loop;
  update public.allowed_users
     set invite_salt = salt,
         invite_hash = encode(digest(salt || ':' || code, 'sha256'), 'hex'),
         invite_issued_at = now(),
         failed_attempts = 0,
         locked_until = null
   where username = uname;
  if not found then raise exception 'user_not_found: додай нік у allowed_users'; end if;
  return substr(code, 1, 4) || '-' || substr(code, 5, 4) || '-' || substr(code, 9, 4);
end
$function$

CREATE OR REPLACE FUNCTION public.load_progress()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := public.my_allowed_id();
  r   public.progress;
begin
  if uid is null then raise exception 'session_replaced'; end if;
  select * into r from public.progress where user_id = uid;
  if not found then return null; end if;
  return json_build_object('state', r.state, 'updated_ms', (extract(epoch from r.updated_at) * 1000)::bigint);
end
$function$

CREATE OR REPLACE FUNCTION public.save_progress(p_state jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := public.my_allowed_id();
  t   timestamptz := now();
  tot int := 0;
  cor int := 0;
begin
  if uid is null then raise exception 'session_replaced'; end if;
  if pg_column_size(p_state) > 1000000 then raise exception 'state_too_large'; end if;
  if (p_state ->> 'answersTotal') ~ '^[0-9]{1,8}$' then tot := (p_state ->> 'answersTotal')::int; end if;
  if (p_state ->> 'answersCorrect') ~ '^[0-9]{1,8}$' then cor := (p_state ->> 'answersCorrect')::int; end if;
  cor := least(cor, tot);
  insert into public.progress (user_id, state, updated_at, answers_total, answers_correct) values (uid, p_state, t, tot, cor)
  on conflict (user_id) do update set
    state = excluded.state,
    updated_at = excluded.updated_at,
    answers_total = excluded.answers_total,
    answers_correct = excluded.answers_correct;
  return (extract(epoch from t) * 1000)::bigint;
end
$function$
